  "verbo-38": {"promptNative": "Voi _____ (beber = bere) succo d’arancia. (vosotros)", "explain": "Vosotros dei verbi '-er' finisce in '-éis': bebéis. 'Beben' è ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"beben": "'beben' è la forma di ellos/ellas.", "bebemos": "'bebemos' è la forma di nosotros.", "bebe": "'bebe' è la forma di él/ella."}},
  "verbo-39": {"promptNative": "Voi _____ (estudiar = studiare) molto per l’esame. (vosotras)", "explain": "Vosotros dei verbi '-ar' finisce in '-áis': estudiáis. 'Estudian' è ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"estudian": "'estudian' è la forma di ellos/ellas.", "estudiamos": "'estudiamos' è la forma di nosotros.", "estudia": "'estudia' è la forma di él/ella."}},
  "verbo-40": {"promptNative": "Tu _____ (poder = potere) farlo da solo. (tú)", "explain": "'Poder' con tú dittonga: puedes (o→ue).", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"puedo": "'puedo' è la forma di yo.", "puede": "'puede' è la forma di él/ella.", "podéis": "'podéis' è la forma di vosotros."}},
  "verbo-41": {"promptNative": "Noi _____ (ir = andare) al mare d’estate.", "explain": "'Ir' con nosotros è 'vamos'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"vais": "'vais' è la forma di vosotros.", "van": "'van' è la forma di ellos/ellas.", "voy": "'voy' è la forma di yo."}},
  "verbo-42": {"promptNative": "Ieri voi _____ (hablar = parlare) con il professore. (vosotros)", "explain": "'Ayer' → passato remoto; vosotros usa '-asteis': hablasteis. 'Hablaron' è il passato remoto di ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"hablaron": "'hablaron' è la forma di ellos/ellas.", "hablabais": "'hablabais' è la forma di vosotros all’imperfetto.", "habláis": "'habláis' è la forma di vosotros al presente."}},
  "verbo-43": {"promptNative": "Ieri sera voi _____ (comer = mangiare) al ristorante. (vosotras)", "explain": "Il passato remoto di vosotros dei verbi '-er/-ir' è '-isteis': comisteis. 'Comieron' è ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"comieron": "'comieron' è la forma di ellos/ellas.", "comíais": "'comíais' è la forma di vosotros all’imperfetto.", "coméis": "'coméis' è la forma di vosotros al presente."}},
  "verbo-44": {"promptNative": "L’anno scorso voi _____ (vivir = abitare) a Siviglia. (vosotros)", "explain": "'El año pasado' → passato remoto; vosotros è 'vivisteis'. 'Vivieron' è la forma di ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"vivieron": "'vivieron' è la forma di ellos/ellas.", "vivíais": "'vivíais' è la forma di vosotros all’imperfetto.", "vivís": "'vivís' è la forma di vosotros al presente."}},
  "verbo-45": {"promptNative": "Ieri voi _____ (ir = andare) al cinema, no? (vosotros)", "explain": "Il passato remoto di 'ir' per vosotros è 'fuisteis'. 'Fueron' è ustedes; 'ibais' è imperfetto.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"fueron": "'fueron' è la forma di ellos/ellas.", "ibais": "'ibais' è la forma di vosotros all’imperfetto.", "vais": "'vais' è la forma di vosotros al presente."}},
  "verbo-46": {"promptNative": "La settimana scorsa voi _____ (tener = avere) un esame. (vosotros)", "explain": "'Tener' usa la radice irregolare 'tuv-'; vosotros: tuvisteis. 'Tuvieron' è ustedes.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"tuvieron": "'tuvieron' è la forma di ellos/ellas.", "teníais": "'teníais' è la forma di vosotros all’imperfetto.", "tenéis": "'tenéis' è la forma di vosotros al presente."}},
