  "verbo-100": {"promptNative": "Spero che noi _____ (conseguir = ottenere) i biglietti per il concerto. (nosotros)", "explain": "'Ojalá' richiede il congiuntivo; 'conseguir' fa e→i e perde la u, dando 'consigamos'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"conseguimos": "'conseguimos' è la forma di nosotros al presente.", "consigan": "'consigan' è la forma di ellos/ellas.", "consiga": "'consiga' è la forma di yo o él/ella."}},
  "verbo-101": {"promptNative": "Preferisco che voi _____ (elegir = scegliere) il ristorante questa volta. (vosotros)", "explain": "'Preferir que' vuole il congiuntivo; 'elegir' fa e→i con g→j, dando 'elijáis'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"elegís": "'elegís' è la forma di vosotros al presente.", "elijan": "'elijan' è la forma di ellos/ellas.", "elijas": "'elijas' è la forma di tú."}},
  "verbo-102": {"promptNative": "È meglio che voi _____ (coger = prendere) la metropolitana; c’è traffico. (vosotros)", "explain": "'Es mejor que' richiede il congiuntivo; 'coger' cambia g→j davanti ad a, dando 'cojáis'. 'Coger' è quotidiano in Spagna ma si evita in gran parte dell’America Latina.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"cogéis": "'cogéis' è la forma di vosotros al presente.", "cojan": "'cojan' è la forma di ellos/ellas.", "cojamos": "'cojamos' è la forma di nosotros."}},
  "verbo-103": {"promptNative": "Appena voi _____ (llegar = arrivare) alla stazione, mandatemi un messaggio. (vosotros)", "explain": "'En cuanto' con riferimento al futuro vuole il congiuntivo; la forma di vosotros è 'lleguéis'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"llegáis": "'llegáis' è la forma di vosotros al presente.", "lleguen": "'lleguen' è la forma di ellos/ellas.", "llegue": "'llegue' è la forma di yo o él/ella."}},
  "verbo-104": {"promptNative": "Non _____ (hacer = fare) tanto rumore; il bambino dorme. (vosotros)", "explain": "L’imperativo negativo di vosotros usa il congiuntivo presente: 'no hagáis'. 'No hagan' è l’imperativo di ustedes dell’America Latina.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"hacéis": "'hacéis' è la forma di vosotros al presente.", "hagan": "'hagan' è la forma di ellos/ellas.", "hagas": "'hagas' è la forma di tú."}},
  "verbo-105": {"promptNative": "Non _____ (preocuparse = preoccuparsi); andrà tutto bene. (vosotros)", "explain": "Imperativo negativo di vosotros di un verbo riflessivo: 'no os preocupéis'. L’indicativo 'preocupáis' è la trappola.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"preocupáis": "'preocupáis' è la forma di vosotros al presente.", "preocupen": "'preocupen' è la forma di ellos/ellas.", "preocupes": "'preocupes' è la forma di tú."}},
  "verbo-106": {"promptNative": "Non _____ (decir = dire) ancora niente a vostra madre. (vosotros)", "explain": "Imperativo negativo di vosotros: 'no digáis'. 'Vuestra' segna anche il registro peninsulare (rispetto a 'su' in America Latina).", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"decís": "'decís' è la forma di vosotros al presente.", "digan": "'digan' è la forma di ellos/ellas.", "digas": "'digas' è la forma di tú."}},
