  "verbo-125": {"promptNative": "Immagino che voi _____ (ver = vedere) già le notizie, no? (vosotros)", "explain": "Il futuro anteriore può esprimere probabilità sul passato recente: 'habréis visto' (= probabilmente avete visto).", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"hayáis visto": "'hayáis visto' non è la forma giusta qui.", "habrán visto": "'habrán visto' non è la forma giusta qui.", "hubierais visto": "'hubierais visto' non è la forma giusta qui."}},
  "verbo-126": {"promptNative": "È possibile che loro _____ (irse = andarsene) già quando arriveremo. (ellos)", "explain": "'Es posible que' con un’azione conclusa usa il congiuntivo passato: 'se hayan ido'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"han ido": "'han ido' è la forma di ellos/ellas al passato prossimo.", "habrán ido": "'habrán ido' non è la forma giusta qui.", "hubieran ido": "'hubieran ido' non è la forma giusta qui."}},
  "verbo-127": {"promptNative": "È un peccato che voi non _____ (poder = potere) venire al matrimonio. (vosotros)", "explain": "Una reazione emotiva a un fatto passato concluso usa il congiuntivo passato: 'hayáis podido'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habéis podido": "'habéis podido' è la forma di vosotros al passato prossimo.", "hayan podido": "'hayan podido' non è la forma giusta qui.", "pudierais": "'pudierais' è la forma di vosotros al congiuntivo imperfetto."}},
  "verbo-128": {"promptNative": "_____ (pasar = succedere) quel che deve succedere, mantieni la calma.", "explain": "La formula fissa 'pase lo que pase' raddoppia il congiuntivo; il primo verbo è 'Pase'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"Pasa": "'Pasa' non è la forma giusta qui.", "Pasará": "'Pasará' non è la forma giusta qui.", "Pasaría": "'Pasaría' non è la forma giusta qui."}},
