  "verbo-131": {"promptNative": "Per quanto _____ (correr = correre), non arriverete in orario. (vosotros)", "explain": "'Por mucho que' con valore ipotetico vuole il congiuntivo: 'corráis'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"corréis": "'corréis' è la forma di vosotros al presente.", "corran": "'corran' è la forma di ellos/ellas.", "corramos": "'corramos' è la forma di nosotros."}},
  "verbo-132": {"promptNative": "Se voi _____ (saber = sapere) la verità, avreste agito diversamente. (vosotros)", "explain": "La frase con 'si' di una condizione irreale nel passato usa il congiuntivo trapassato: 'hubierais sabido'; il condizionale composto va nel risultato.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habríais sabido": "'habríais sabido' è la forma di vosotros al condizionale passato.", "hubieran sabido": "'hubieran sabido' non è la forma giusta qui.", "habíais sabido": "'habíais sabido' è la forma di vosotros al trapassato prossimo."}},
  "verbo-133": {"promptNative": "Se me lo aveste detto prima, io vi _____ (ayudar = aiutare). (yo)", "explain": "Il risultato di una condizione irreale passata usa il condizionale composto: 'habría ayudado'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habré ayudado": "'habré ayudado' non è la forma giusta qui.", "habrían ayudado": "'habrían ayudado' è la forma di ellos/ellas.", "había ayudado": "'había ayudado' è la forma di yo al trapassato prossimo."}},
  "verbo-134": {"promptNative": "Se foste arrivati in orario, voi _____ (ver = vedere) l’inizio del film. (vosotros)", "explain": "La frase del risultato di una condizione irreale nel passato vuole il condizionale composto 'habríais visto'; il futuro anteriore 'habréis visto' non può esprimere il controfattuale. 'Peli' è colloquiale peninsulare per film.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habréis visto": "'habréis visto' non è la forma giusta qui.", "habrían visto": "'habrían visto' è la forma di ellos/ellas.", "habíais visto": "'habíais visto' è la forma di vosotros al trapassato prossimo."}},
  "verbo-135": {"promptNative": "Se loro _____ (venir = venire), la festa sarebbe stata molto più bella. (ellos)", "explain": "La frase con 'si' vuole il congiuntivo trapassato 'hubieran venido'; il condizionale composto resta nel risultato.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habrían venido": "'habrían venido' è la forma di ellos/ellas al condizionale passato.", "hubieras venido": "'hubieras venido' non è la forma giusta qui.", "habían venido": "'habían venido' è la forma di ellos/ellas al trapassato prossimo."}},
  "verbo-136": {"promptNative": "Avrei voluto che voi me lo _____ (contar = dire) prima di firmare il contratto. (vosotros)", "explain": "'Ojalá' che esprime rimpianto per il passato vuole il congiuntivo trapassato: 'hubierais contado'.", "wrongNote": "Solo un’opzione concorda con il soggetto e il tempo/modo della frase — le altre sono forme sbagliate del verbo.", "distractorNotes": {"habríais contado": "'habríais contado' è la forma di vosotros al condizionale passato.", "hubieran contado": "'hubieran contado' non è la forma giusta qui.", "contarais": "'contarais' è la forma di vosotros al congiuntivo imperfetto."}},
